<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { ArrowRight, BarChart3, Building2, Check, ChevronRight, CircleHelp, GitCompareArrows, GraduationCap, History, Layers3, ListChecks, RefreshCw, ScanLine, Sparkles, TrendingUp, X } from 'lucide-vue-next'
import { chosen, clearSelection, load, state, toggle } from './state'
const route = useRoute()
const nav = [
  { path: '/plans', name: '招生计划', icon: GraduationCap, subtitle: '2027 专业与名额' },
  { path: '/history', name: '历年录取', icon: History, subtitle: '分数线与复录比' },
  { path: '/overview', name: '院校图览', icon: BarChart3, subtitle: '数据可视化' },
  { path: '/school', name: '院校档案', icon: Building2, subtitle: '招生 · 历史 · 经验' },
  { path: '/heat', name: '平台热度', icon: TrendingUp, subtitle: '关注与讨论' },
  { path: '/compare', name: '院校比较', icon: GitCompareArrows, subtitle: '我的候选清单' },
  { path: '/recommend', name: '偏好推荐', icon: Sparkles, subtitle: '专业、类别与背景' },
  { path: '/game', name: '胜利指数', icon: Layers3, subtitle: '分数 · 背景 · 热度' },
  { path: '/tasks', name: '信息采集', icon: ListChecks, subtitle: '登录 · JSON · 进度' },
]
const current = computed(() => nav.find(x => x.path === route.path) || nav[0]!)
const headings: Record<string, string[]> = { '/school': ['每所院校，都有自己的档案', '招生、历年录取、讨论与经验信息，按院校持续整理。'], '/plans': ['找到值得关注的专业', '专业、科目与招生名额，放在一起看清楚。'], '/history': ['回看往年，做好今年的选择', '复试线、录取分数与人数，按年度和统计范围分别展示。'], '/overview': ['让院校数据更直观', '用同口径的数字，发现候选专业之间的区别。'], '/heat': ['看看院校的热度', '把讨论和搜索信号整理成一个热度值。'], '/compare': ['把候选院校，放在一起', '并排查看专业数据，再按你的看重点填写偏好。'], '/recommend': ['先选适合你的专业', '无需初试成绩，按专业与类别偏好发现候选。'], '/game': ['找到更有胜算的选择', '填写你的分数、层次意愿和背景，结合热度计算各校胜利指数。'], '/tasks': ['每一次更新，都有进度', '查看本次任务的完成情况与结果。'] }
const heading = computed(() => headings[route.path] || headings['/plans']!)
const notes = computed(() => (state.data?.official_notes || []).filter(n => !state.unit || n.unit === state.unit))
let timer: ReturnType<typeof setInterval>
onMounted(() => { load(); timer = setInterval(() => { if (!document.hidden) load() }, 60000) })
onBeforeUnmount(() => clearInterval(timer))
</script>
<template><div class="app-shell"><aside class="sidebar"><a href="#/plans" class="brand"><span class="brand-symbol"><ScanLine :size="25" /></span><span>GradHeat<small>考研择校工作台</small></span></a><div class="year-badge"><span />2027 入学 · 11408</div><p class="nav-label">我的择校</p><nav aria-label="主要导航"><RouterLink v-for="item in nav" :key="item.path" :to="item.path" class="nav-item"><component :is="item.icon" :size="19" /><span>{{ item.name }}<small>{{ item.subtitle }}</small></span><span v-if="item.path === '/compare' && chosen.length" class="nav-count">{{ chosen.length }}</span></RouterLink></nav><div class="sidebar-card"><CircleHelp :size="20" /><strong>让每个选择都有依据</strong><p>未知数据保持未知，<br>核对后再用于决策。</p></div><div class="sidebar-bottom"><span class="online-dot" />招生资料持续更新</div></aside><main class="main"><header class="topbar"><div><Building2 :size="16" /><span>择校工作台</span><ChevronRight :size="14" /><b>{{ current.name }}</b></div><button class="text-button" :disabled="state.loading" @click="load"><RefreshCw :size="14" :class="{ spinning: state.loading }" /><span>{{ state.loading ? '正在刷新' : '刷新数据' }}</span></button></header><div class="page-content"><section class="page-heading"><div><div class="eyebrow"><span />2027 GRADUATE ADMISSIONS</div><h1>{{ heading![0] }}</h1><p>{{ heading![1] }}</p></div><div class="update-meta"><span class="online-dot" />资料截至 {{ state.data?.data_as_of || '加载中' }}<small v-if="state.data?.last_checked">最近检查 {{ state.data.last_checked }}</small></div></section><section v-if="state.data" class="stat-strip"><div><span>招生单位</span><strong>{{ state.data.counts.units }}</strong><small>持续补齐</small></div><div><span>11408 专业</span><strong>{{ state.data.counts.matched_programmes }}</strong><small>学硕 + 专硕</small></div><div><span>历年记录</span><strong>{{ state.data.counts.history_rows.toLocaleString() }}</strong><small>按口径分列</small></div><div class="stat-note"><Check :size="17" /><p>两源及以上一致后解除待核；<br>对应官方资料情况在页尾说明。</p></div></section><div v-if="state.error" class="error-banner" role="alert">{{ state.error }}<button class="icon-button" aria-label="关闭提示" @click="state.error = ''"><X :size="16" /></button></div><div v-if="!state.data && state.loading" class="loading-panel"><RefreshCw :size="24" class="spinning" /><p>正在整理招生数据…</p></div><RouterView v-if="state.data || route.path === '/tasks'" /><details v-if="notes.length" class="official-notes"><summary>官方资料核对说明 <span>{{ notes.length }} 项</span></summary><p v-for="note in notes" :key="`${note.unit}-${note.year}-${note.note}`">{{ note.unit }} · {{ note.year }}：{{ note.note }}</p></details><footer>“—”表示尚未取得或无法确认。招生计划与历年统计保留各自的适用范围。</footer></div></main><Transition name="tray"><div v-if="chosen.length && route.path !== '/compare'" class="compare-tray"><span class="tray-icon"><GitCompareArrows :size="22" /></span><div><strong>已选 {{ chosen.length }} 个专业</strong><span class="tray-labels">{{ chosen.map(p => p.unit).join('、') }}</span></div><div class="tray-chips"><span v-for="p in chosen.slice(0, 3)" :key="p.id">{{ p.unit }}<button :aria-label="`移除${p.unit}${p.major_name}`" @click="toggle(p.id)"><X :size="12" /></button></span></div><button class="text-button" @click="clearSelection">清空</button><RouterLink to="/compare" class="button">开始比较<ArrowRight :size="15" /></RouterLink></div></Transition></div></template>
